 sOutput += "<p>You searched for <b>" + Original +".</b>";
  } 
  ////////////
function WriteDocEnd() {
 var iTotalMatched=0;
 if (!(bWildcardError)) {
  for( var i=1; i<page.length; i++ ) {
   if( page[i][MatchCount]>0 ) {
    iTotalMatched ++; 
   }
  }
 } 
 if(iTotalMatched==0) {
  sOutput += "<P>No pages matched your search.&nbsp;&nbsp;";
  }
  else
  {
   var sPlural = iTotalMatched==1 ? "" : "s"; sOutput += "<P>" + iTotalMatched + " page" + sPlural + " listed.&nbsp;&nbsp;"; } sOutput += "<A href=\"javascript:history.go(-1)\"><B>Search Again</B></A></P>"; sOutput ; //+= "</p></body></html>"; 
   } 
